const webPlayerHtml = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Tangerine</title><style>
:root{color-scheme:dark;--canvas:#191919;--panel:#222120;--raised:#292827;--text:#f0ece8;--muted:#b3aba5;--line:#403c38;--accent:#d37918}
*{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--text);font:15px system-ui,sans-serif}button,input,select,textarea{font:inherit}button{cursor:pointer;background:var(--raised);color:var(--text);border:1px solid var(--line);border-radius:6px;padding:10px 16px}button:hover,button:focus-visible{border-color:var(--accent)}button.primary{background:var(--accent);color:#381a04;border:0;font-weight:600}input,select,textarea{background:#0e0e0e;color:var(--text);border:1px solid var(--line);border-radius:6px;padding:12px;max-width:100%}input:focus-visible,textarea:focus-visible{outline:2px solid var(--accent)}header{padding:18px 24px;border-bottom:1px solid var(--line);display:flex;gap:12px;align-items:center;background:var(--panel)}.logo{color:var(--accent);font-size:28px}h1{font-size:22px;margin:0}h2{font-size:28px;margin:0 0 12px}p{color:var(--muted);line-height:1.6}.spacer{flex:1}main{max-width:1440px;margin:auto;padding:28px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:8px;padding:24px}.pair{max-width:540px;margin:50px auto}label{display:grid;gap:8px;margin:16px 0}.toolbar{display:flex;gap:12px;flex-wrap:wrap;margin:20px 0}.toolbar input{flex:1;min-width:180px}.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:18px}.card{text-align:left;padding:0;overflow:hidden;background:var(--panel);min-width:0}.art{aspect-ratio:16/9;background:var(--raised);display:grid;place-items:center;font-size:40px;color:var(--accent)}.card strong,.card small{display:block;margin:12px;overflow-wrap:anywhere}.card small{color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:1px}.status{min-height:24px;color:var(--accent);overflow-wrap:anywhere}.hidden,[hidden]{display:none!important}dialog{background:var(--canvas);color:var(--text);border:1px solid var(--line);border-radius:10px;width:min(1100px,96vw);max-height:94dvh;padding:18px}dialog::backdrop{background:#000c}.player-head{display:flex;align-items:center;gap:12px;margin-bottom:16px}.player-head strong{flex:1;overflow-wrap:anywhere}video,audio{width:100%;max-height:60dvh;background:#0e0e0e}iframe{width:100%;height:60dvh;background:white;border:0}#picture{max-width:100%;max-height:60dvh;display:block;margin:auto}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:55dvh;overflow:auto}.study{margin-top:18px;border-top:1px solid var(--line);padding-top:16px}.study textarea{width:100%;min-height:70px}.note{padding:12px 0;border-bottom:1px solid var(--line);white-space:pre-wrap;overflow-wrap:anywhere}.muted{color:var(--muted)}@media(max-width:600px){main{padding:16px}.pair{margin:16px auto}.panel{padding:18px}header{padding:14px 16px}.grid{grid-template-columns:repeat(auto-fill,minmax(150px,1fr))}dialog{padding:12px}.toolbar{gap:8px}}
</style></head><body>
<header><span class="logo" aria-hidden="true">▶</span><h1>Tangerine</h1><span id="serverName" class="muted"></span><span class="spacer"></span><button id="disconnect" hidden>Disconnect</button></header>
<main><section id="pair" class="panel pair"><h2>Your media, everywhere.</h2><p>Pair this browser with your Tangerine server to watch, listen, read, and keep your study notes together.</p>
<form id="pairForm"><label>This player’s name<input id="deviceName" maxlength="80" value="Browser player" required autocomplete="off"></label><label>Pairing code<input id="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required autocomplete="one-time-code" placeholder="Six digits from the Server screen"></label><button class="primary" id="pairButton">Pair this player</button></form><p>Use a trusted private network. HTTP traffic is authenticated but unencrypted.</p></section>
<section id="hostRemote" class="panel" hidden><h3>Control host player</h3><p id="hostNow">No player open</p><div class="toolbar"><button id="hostPrevious">Previous</button><button id="hostPlay">Play</button><button id="hostPause">Pause</button><button id="hostBack">Back 10s</button><button id="hostForward">Forward 10s</button><button id="hostNext">Next</button></div><p id="hostStatus" class="status" role="status"></p></section><section id="library" hidden><h2>Your library</h2><p>Video, music, documents, and learning. Streamed from your own server.</p><div class="toolbar"><select id="category" aria-label="Media category"><option value="all">All media</option><option value="video">Videos</option><option value="audio">Music</option><option value="documents">Documents</option></select><select id="collection" aria-label="Library"><option value="all">All libraries</option></select><input id="search" type="search" placeholder="Search your media" aria-label="Search media"><button id="refresh">Refresh</button></div><div id="items" class="grid"></div><div class="toolbar"><button id="prevPage" disabled>Previous page</button><button id="nextPage" disabled>Next page</button></div><p id="count" class="muted"></p></section><p id="status" class="status" role="status" aria-live="polite"></p></main>
<dialog id="player"><div class="player-head"><strong id="mediaTitle"></strong><button id="closePlayer" aria-label="Close player">Close</button></div><video id="video" controls playsinline hidden></video><audio id="audio" controls hidden></audio><iframe id="document" title="Document preview" hidden></iframe><img id="picture" alt="Selected media" hidden><pre id="text" hidden></pre><p id="unsupported" hidden>This resource needs a compatible native app. Browser playback depends on the browser’s supported formats.</p><p id="playerStatus" role="status" class="status"></p><a id="openPdf" target="_blank" rel="noopener" hidden>Open PDF separately</a><div class="toolbar"><label>Playback speed<select id="speed"><option>0.25</option><option>0.5</option><option>0.75</option><option selected>1</option><option>1.25</option><option>1.5</option><option>2</option><option>3</option><option>4</option></select></label><button id="bookmark">Bookmark position</button></div><section id="studyPanel" class="study"><h3 id="studyHeading">Notes &amp; bookmarks</h3><label>Note<textarea id="noteInput" maxlength="100000" placeholder="Capture an idea or a timestamped note"></textarea></label><button id="saveNote" class="primary">Save note</button><div class="toolbar" role="group" aria-label="Study entries"><button id="studyNotes" aria-pressed="true">Notes</button><button id="studyBookmarks" aria-pressed="false">Bookmarks</button><input id="studySearch" type="search" maxlength="256" placeholder="Search this title’s Study entries" aria-label="Search Study"><button id="studyFind">Search</button></div><div id="notes" aria-live="polite"></div><div class="toolbar"><button id="studyPrevious" disabled>Previous</button><button id="studyNext" disabled>Next</button><button id="studyRefresh">Refresh entries</button></div><p id="studyStatus" class="status" role="status"></p></section></dialog>
<script>
'use strict';
const $=id=>document.getElementById(id);
let snapshot=null,deviceId=null,current=null,media=null,lastSave=0,saveChain=Promise.resolve(),textRequest=0;
let pagedStudy=false,studyKind='notes',studyCursor=null,studyNext=null,studyHistory=[],studyRows=[],studyAnchors={},studyGeneration=0,studyBusy=false;
let modern=false,catalogCursor=null,nextCatalogCursor=null,catalogHistory=[],catalogGeneration=0;
const request=async(path,body)=>{const response=await fetch(path,{method:body?'POST':'GET',credentials:'same-origin',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});if(!response.ok){if(response.status===401){$('pair').hidden=false;$('library').hidden=true;$('disconnect').hidden=true;}throw new Error(response.status===401?'Pairing is required or access was revoked. Check the current server code.':response.status===403?'This device does not have permission for that action. Check this library’s access on the host.':'The server could not complete this request.');}return response.json();};
const status=message=>$('status').textContent=message;
const title=item=>item.userTitle||item.metadata?.title||item.title||item.filename;
const id=()=>`web-${Date.now()}-${Math.random().toString(36).slice(2)}`;
async function load(){const session=await request('/v1/session');deviceId=session.deviceId;modern=session.protocolVersion>=2;pagedStudy=(session.capabilities||[]).includes('study-pages-v1');catalogCursor=null;catalogHistory=[];
 snapshot=modern?{schemaVersion:3,libraries:session.libraries||[],items:[],playback:[],reading:[],notes:[],bookmarks:[]}:await request('/v1/snapshot');
 $('pair').hidden=true;$('library').hidden=false;$('disconnect').hidden=false;$('serverName').textContent=session.name;
 const selected=$('collection').value;$('collection').replaceChildren(new Option('All libraries','all'));for(const library of snapshot.libraries)$('collection').add(new Option(library.title,library.id));
 if([...$('collection').options].some(option=>option.value===selected))$('collection').value=selected;
 if(modern)await loadCatalogPage();else render();await loadHostRemote().catch(()=>{});}
async function loadCatalogPage(){const generation=++catalogGeneration,params=new URLSearchParams({limit:'60'}),library=$('collection').value,kind=$('category').value;
 if(library!=='all')params.set('library',library);if(kind!=='all')params.set('type',kind);if($('search').value.trim())params.set('q',$('search').value.trim());if(catalogCursor)params.set('cursor',catalogCursor);
 const page=await request('/v2/catalog?'+params);if(generation!==catalogGeneration||!snapshot)return;
 snapshot.items=page.items;nextCatalogCursor=page.next;snapshot.playback=page.items.flatMap(item=>item.playback?[item.playback]:[]);snapshot.reading=page.items.flatMap(item=>item.reading?[item.reading]:[]);render();}
$('prevPage').onclick=()=>{catalogCursor=catalogHistory.pop()??null;loadCatalogPage().catch(error=>status(error.message));};
$('nextPage').onclick=()=>{if(!nextCatalogCursor)return;catalogHistory.push(catalogCursor);catalogCursor=nextCatalogCursor;loadCatalogPage().catch(error=>status(error.message));};

function render(){const query=$('search').value.toLowerCase(),kind=$('category').value,library=$('collection').value;const items=modern?snapshot.items:snapshot.items.filter(item=>!item.unavailable&&(library==='all'||item.libraryId===library)&&(kind==='all'||(kind==='documents'?!['video','audio'].includes(item.itemType):item.itemType===kind))&&title(item).toLowerCase().includes(query));$('items').replaceChildren();for(const item of items.slice(0,240)){const card=document.createElement('button');card.className='card';const art=document.createElement('div');art.className='art';art.textContent=item.itemType==='audio'?'♫':item.itemType==='video'?'▶':'▤';if(modern){const image=document.createElement('img');image.loading='lazy';image.decoding='async';image.alt='';image.src='/v2/artwork/'+encodeURIComponent(item.id);image.style.cssText='width:100%;height:100%;object-fit:cover';image.onerror=()=>image.remove();art.append(image);}const name=document.createElement('strong');name.textContent=title(item);const type=document.createElement('small');type.textContent=`${item.itemType} · Server`;card.append(art,name,type);card.onclick=()=>openItem(item).catch(error=>status(error.message));$('items').append(card);}$('prevPage').disabled=!modern||catalogHistory.length===0;$('nextPage').disabled=!modern||!nextCatalogCursor;$('count').textContent=modern?`Page ${catalogHistory.length+1} · ${items.length} items`:items.length>240?`Showing 240 of ${items.length} items. Search to narrow your library.`:`${items.length} items`;}
function enqueue(body){const task=saveChain.catch(()=>{}).then(()=>request('/v1/snapshot',{schemaVersion:snapshot.schemaVersion,...body}));saveChain=task;return task;}
function saveProgress(ended=false){if(!media||!current||!Number.isFinite(media.duration)||media.duration<=0)return Promise.resolve();const item=current,position=media.currentTime,duration=media.duration,speed=media.playbackRate;let previous=(snapshot.playback||[]).find(row=>row.itemId===item.id);const completed=previous?.manualCompletion??(previous?.completed||ended||position/duration>=0.9),now=Date.now();const row={itemId:item.id,lastPositionSeconds:position,resumePositionSeconds:completed?0:Math.max(0,position-10),durationSeconds:duration,percentWatched:completed?100:Math.max(previous?.percentWatched||0,position/duration*100),completed,manualCompletion:previous?.manualCompletion??null,playbackSpeed:speed,lastOpenedAt:now,lastEventAt:now,deviceId,version:(previous?.version||0)+1};snapshot.playback=(snapshot.playback||[]).filter(value=>value.itemId!==item.id);snapshot.playback.push(row);return enqueue({playback:[row]}).catch(error=>{$('playerStatus').textContent='Progress could not be saved. Keep this player open and retry when the server is available.';throw error;});}
async function closeMedia(){++textRequest;++studyGeneration;studyBusy=false;if(media){media.pause();await saveProgress().catch(()=>{});media.removeAttribute('src');media.load();}media=null;current=null;$('document').removeAttribute('src');$('picture').removeAttribute('src');$('text').textContent='';}
async function openItem(item){await closeMedia();current=item;const notesAvailable=item.libraryKind==='courses'||['pdf','epub','cbz','txt','html'].includes(item.itemType);$('studyPanel').hidden=!notesAvailable;$('bookmark').hidden=!notesAvailable;$('studyHeading').textContent=item.libraryKind==='courses'?'Study':'Notes & bookmarks';studyKind='notes';studyCursor=null;studyNext=null;studyHistory=[];studyRows=[];studyAnchors={};$('studySearch').value='';$('studyStatus').textContent='';renderStudyEntries();if(notesAvailable)void loadStudyPage().catch(error=>{if(current===item)$('studyStatus').textContent=error.message;});$('mediaTitle').textContent=title(item);$('openPdf').hidden=true;$('playerStatus').textContent='';$('noteInput').value='';for(const key of ['video','audio','document','picture','text','unsupported'])$(key).hidden=true;const source=`/v1/media/${encodeURIComponent(item.id)}`;if(['video','audio'].includes(item.itemType)){media=$(item.itemType);media.hidden=false;const progress=(snapshot.playback||[]).find(row=>row.itemId===item.id);media.onloadedmetadata=()=>{media.playbackRate=progress?.playbackSpeed||1;$('speed').value=String(media.playbackRate);if(progress&&!progress.completed){media.currentTime=Math.min(Math.max(0,progress.lastPositionSeconds-10),Math.max(0,media.duration-0.1));}};media.onerror=()=>{$('playerStatus').textContent='This browser could not play this file. Try a supported format or use a native Tangerine player.';};media.src=source;media.load();}else if(item.itemType==='pdf'){$('document').hidden=false;$('document').src=source;$('openPdf').hidden=false;$('openPdf').href=source;$('playerStatus').textContent='If this browser cannot display the PDF preview, open it separately or use a native Tangerine player.';}else if(item.itemType==='image'){$('picture').hidden=false;$('picture').src=source;}else if(['txt','html'].includes(item.itemType)){const generation=++textRequest;$('text').hidden=false;const response=await fetch(source,{credentials:'same-origin'});if(!response.ok)throw new Error('The document could not be loaded.');const reader=response.body.getReader();let chunks=[],size=0;while(true){const part=await reader.read();if(part.done)break;size+=part.value.byteLength;if(size>2*1024*1024){await reader.cancel();throw new Error('Open this large text document in a native player.');}chunks.push(part.value);}if(generation!==textRequest)return;const bytes=new Uint8Array(size);let offset=0;for(const chunk of chunks){bytes.set(chunk,offset);offset+=chunk.length;}$('text').textContent=new TextDecoder().decode(bytes);}else{$('unsupported').hidden=false;}renderNotes();$('bookmark').disabled=!media;$('speed').disabled=!media;if(!$('player').open)$('player').showModal();}
function studyControls(){
 $('studyNotes').setAttribute('aria-pressed',String(studyKind==='notes'));$('studyBookmarks').setAttribute('aria-pressed',String(studyKind==='bookmarks'));
 $('studyPrevious').disabled=studyBusy||studyHistory.length===0;$('studyNext').disabled=studyBusy||!studyNext;
 $('studyFind').disabled=studyBusy;$('studyRefresh').disabled=studyBusy;
}
function renderStudyEntries(){
 $('notes').replaceChildren();studyControls();
 if(!studyRows.length){const empty=document.createElement('p');empty.className='muted';empty.textContent=studyBusy?'Loading Study entries…':'No matching '+studyKind+' on this page.';$('notes').append(empty);return;}
 for(const entry of studyRows){const row=document.createElement('div');row.className='note';const content=document.createElement('div');content.textContent=studyKind==='notes'?entry.content:entry.title;row.append(content);
  if(studyKind==='bookmarks'&&entry.description){const description=document.createElement('p');description.textContent=entry.description;row.append(description);}
  const anchor=studyAnchors[entry.id];if(anchor?.textRange?.quote){const quote=document.createElement('blockquote');quote.textContent=anchor.textRange.quote;row.append(quote);}
  if(entry.positionSeconds!=null&&media){const jump=document.createElement('button');jump.textContent='Jump to '+Math.floor(entry.positionSeconds/60)+':'+String(Math.floor(entry.positionSeconds%60)).padStart(2,'0');jump.onclick=()=>{if(media)media.currentTime=Math.max(0,Math.min(media.duration||Infinity,entry.positionSeconds));};row.append(jump);}
  else if(entry.pageNumber!=null){const location=document.createElement('small');location.textContent='Page '+entry.pageNumber+(anchor?.textRange?' · passage restoration is available in the native reader':'');row.append(location);}
  $('notes').append(row);
 }
}
async function loadStudyPage(){
 const item=current;if(!item||!snapshot)return;const generation=++studyGeneration,kind=studyKind;studyBusy=true;renderStudyEntries();
 try{
  if(pagedStudy){const params=new URLSearchParams({kind,limit:'40',q:$('studySearch').value.trim()});if(studyCursor)params.set('cursor',studyCursor);
   const page=await request('/v2/study/'+encodeURIComponent(item.id)+'?'+params);if(generation!==studyGeneration||current!==item)return;studyRows=page.entries;studyAnchors=page.anchors||{};studyNext=page.next;
  }else{if(modern){const study=await request('/v2/study/'+encodeURIComponent(item.id));if(generation!==studyGeneration||current!==item)return;snapshot.notes=study.notes;snapshot.bookmarks=study.bookmarks;}
   const q=$('studySearch').value.toLowerCase(),all=(snapshot[kind]||[]).filter(entry=>entry.itemId===item.id&&!entry.deleted&&(kind==='notes'?entry.content:entry.title+' '+(entry.description||'')).toLowerCase().includes(q));
   const offset=Number(studyCursor||0);studyRows=all.slice(offset,offset+40);studyNext=all.length>offset+40?String(offset+40):null;studyAnchors={};
  }
  $('studyStatus').textContent='Page '+(studyHistory.length+1)+' · '+studyRows.length+' '+kind;
 }finally{if(generation===studyGeneration){studyBusy=false;renderStudyEntries();}}
}
function resetStudy(kind=studyKind){studyKind=kind;studyCursor=null;studyNext=null;studyHistory=[];studyRows=[];return loadStudyPage();}
function studyAction(action){action().catch(error=>$('studyStatus').textContent=error.message);}
$('studyNotes').onclick=()=>studyAction(()=>resetStudy('notes'));$('studyBookmarks').onclick=()=>studyAction(()=>resetStudy('bookmarks'));
$('studyFind').onclick=()=>studyAction(()=>resetStudy());$('studySearch').onkeydown=event=>{if(event.key==='Enter')studyAction(()=>resetStudy());};
$('studyRefresh').onclick=()=>studyAction(()=>resetStudy());
$('studyPrevious').onclick=()=>{if(studyBusy||!studyHistory.length)return;studyCursor=studyHistory.pop()??null;studyAction(loadStudyPage);};
$('studyNext').onclick=()=>{if(studyBusy||!studyNext)return;studyHistory.push(studyCursor);studyCursor=studyNext;studyAction(loadStudyPage);};
function renderNotes(){renderStudyEntries();}
$('saveNote').onclick=async()=>{if(!current||!$('noteInput').value.trim())return;const item=current,now=Date.now(),note={id:id(),libraryId:item.libraryId,itemId:item.id,content:$('noteInput').value.trim(),positionSeconds:media?.currentTime??null,pageNumber:null,createdAt:now,updatedAt:now,deviceId,version:1,deleted:false};$('saveNote').disabled=true;try{await enqueue({notes:[note]});snapshot.notes=snapshot.notes||[];snapshot.notes.push(note);if(current===item){void resetStudy('notes').catch(error=>$('studyStatus').textContent=error.message);$('noteInput').value='';renderNotes();$('playerStatus').textContent='Note saved.';}}catch(error){$('playerStatus').textContent=error.message;}finally{$('saveNote').disabled=false;}};
$('bookmark').onclick=async()=>{if(!current||!media)return;const now=Date.now(),position=media.currentTime,bookmark={id:id(),libraryId:current.libraryId,itemId:current.id,title:`${title(current)} · ${Math.floor(position/60)}:${String(Math.floor(position%60)).padStart(2,'0')}`,description:null,positionSeconds:position,pageNumber:null,createdAt:now,updatedAt:now,deviceId,version:1,deleted:false};try{await enqueue({bookmarks:[bookmark]});snapshot.bookmarks=snapshot.bookmarks||[];snapshot.bookmarks.push(bookmark);if(current?.id===bookmark.itemId){void resetStudy('bookmarks').catch(error=>$('studyStatus').textContent=error.message);$('playerStatus').textContent='Bookmark saved.';}}catch(error){$('playerStatus').textContent=error.message;}};
$('pairForm').onsubmit=async event=>{event.preventDefault();$('pairButton').disabled=true;try{await request('/v1/pair',{name:$('deviceName').value.trim(),code:$('code').value});$('code').value='';await load();status('Connected to your media server.');}catch(error){status(error.message);}finally{$('pairButton').disabled=false;}};
$('disconnect').onclick=async()=>{await closeMedia();if($('player').open)$('player').close();try{await request('/v1/logout',{});}catch(error){status(error.message);}snapshot=null;$('pair').hidden=false;$('library').hidden=true;$('disconnect').hidden=true;$('serverName').textContent='';status('Disconnected. Pair again to reconnect.');};
$('refresh').onclick=()=>load().then(()=>status('Library refreshed.')).catch(error=>status(error.message));for(const key of ['category','collection','search'])$(key).addEventListener('input',()=>{if(!snapshot)return;if(modern){catalogCursor=null;catalogHistory=[];loadCatalogPage().catch(error=>status(error.message));}else render();});
document.addEventListener('visibilitychange',()=>{if(document.hidden)saveProgress().catch(()=>{});});
let hostPosition=0,hostDuration=0;
async function loadHostRemote(){if($('library').hidden||document.hidden)return;const host=await request('/v1/playback');$('hostRemote').hidden=!host.enabled;if(host.enabled){hostPosition=Number(host.position)||0;hostDuration=Number(host.duration)||0;$('hostNow').textContent=host.active?`${host.title} · ${host.playing?'Playing':'Paused'} · ${Math.floor(hostPosition)} / ${Math.floor(hostDuration)}s`:'Open a player on the host to control it.';}}
async function hostAction(action,value){try{await request('/v1/playback',{action,...(value===undefined?{}:{value})});$('hostStatus').textContent='';await loadHostRemote();}catch(error){$('hostStatus').textContent=error.message;}}
$('hostPrevious').onclick=()=>hostAction('previous');$('hostNext').onclick=()=>hostAction('next');$('hostPlay').onclick=()=>hostAction('play');$('hostPause').onclick=()=>hostAction('pause');$('hostBack').onclick=()=>hostAction('seek',Math.max(0,hostPosition-10));$('hostForward').onclick=()=>hostAction('seek',Math.min(hostDuration,hostPosition+10));
setInterval(()=>loadHostRemote().catch(()=>{}),2000);
load().catch(()=>status('Enter the code shown on your server to connect.'));
</script></body></html>''';
